"""Force TYPE2/TYPE3 nodes (bulk children) and deep chains; verify lookups + images."""
import json, subprocess, sys, collections, random
sys.path.insert(0, '/workspace/tmp/tests')
from ref import Image, Fib, Bad

def make(rng):
    ops = []
    for _ in range(6):
        bl = rng.choice([96, 102, 108, 114])
        base = rng.getrandbits(bl)
        for i in range(rng.randint(7, 40)):
            ln = min(128, bl + 6 + rng.randint(0, 10))
            v = (base << (128 - bl)) | (rng.randrange(64) << max(0, 128 - bl - 6))
            if ln < 128:
                v |= rng.getrandbits(128 - ln)
            v &= (1 << 128) - 1
            v = (v >> (128 - ln)) << (128 - ln)
            ops.append(['put', '%032x' % v, ln, rng.randint(0, 4194302)])
    for _ in range(40):
        ln = rng.choice([124, 125, 126, 127, 128])
        v = (rng.getrandbits(128) >> (128 - ln)) << (128 - ln)
        ops.append(['put', '%032x' % v, ln, rng.randint(0, 4194302)])
    for _ in range(30):
        bl = rng.choice([64, 80])
        base = rng.getrandbits(bl)
        for i in range(rng.randint(3, 20)):
            ln = min(128, bl + rng.randint(1, 20))
            v = (base << (128 - bl)) | rng.getrandbits(128 - bl)
            v &= (1 << 128) - 1
            v = (v >> (128 - ln)) << (128 - ln)
            ops.append(['put', '%032x' % v, ln, rng.randint(0, 4194302)])
    rng.shuffle(ops)
    return ops

def main():
    seed = int(sys.argv[1]) if len(sys.argv) > 1 else 5
    rng = random.Random(seed)
    for round_ in range(6):
        ops = make(rng)
        addrs = []
        for (a, l, h) in [(o[1], o[2], o[3]) for o in ops if o[0] == 'put']:
            addrs.append(a)
            v = int(a, 16)
            if l < 128:
                addrs.append('%032x' % (v | (1 << rng.randrange(l, 128))))
        addrs += ['%032x' % rng.getrandbits(128) for _ in range(100)]
        full = ops + [['save'], ['load_saved', 0],
                      ['query', addrs[:len(addrs)//2]], ['image_query', addrs[len(addrs)//2:]]]
        body = json.dumps({"cases": [{"ops": full}]}, separators=(',', ':'))
        p = subprocess.run([sys.executable, 'run.py'], input=body.encode(), cwd='/workspace',
                           capture_output=True, timeout=300)
        if p.returncode:
            raise SystemExit('rc %d %s' % (p.returncode, p.stderr.decode()[:400]))
        resp = json.loads(p.stdout.decode())
        res = resp['results'][0]
        fib = Fib(); exp = []
        for op in full:
            if op[0] == 'put': fib.put(op[1], op[2], op[3])
            elif op[0] == 'query':
                for a in op[1]: exp.append(fib.lpm(a))
            elif op[0] == 'image_query':
                for a in op[1]: exp.append(None)
        loaded = Image(res['snapshots'][0])
        j = 0
        exp2 = []
        for op in full:
            if op[0] == 'put': fib.put(op[1], op[2], op[3])
            elif op[0] == 'query':
                for a in op[1]: exp2.append(fib.lpm(a))
            elif op[0] == 'image_query':
                for a in op[1]: exp2.append(loaded.lookup(a))
        bad = [(i, a, b) for i, (a, b) in enumerate(zip(exp2, res['answers'])) if a != b]
        tc = collections.Counter(n['type'] for n in loaded.nodes)
        bulk = sum(bin(n.get('bulk_bitmap', 0)).count('1') for n in loaded.nodes)
        print('round %d: types=%s bulk=%d nodes=%d mismatches=%d load=%s' %
              (round_, dict(tc), bulk, len(loaded.nodes), len(bad), res['loads']))
        if bad:
            print(bad[:5]); raise SystemExit(1)
        if tc.get(3, 0) == 0:
            print('WARNING: no TYPE3 node produced')
    print('T3TEST PASS')

main()
